const liverpoolExercises: ExerciseData[] = [
  { title: "Liverpool: Gegenpressing - recuperación en 5 segundos", description: "Ejercicio insignia del gegenpressing de Klopp. Equipo de 5 pierde posesión intencionalmente y debe recuperar en máximo 5 segundos. Si no recupera, el rival puede anotar en arco. Se practican 3 tipos de gegenpressing: pressing al portador, cierre de líneas, y pressing colectivo en zona. Punto clave: los primeros 2 segundos son los más importantes. 10 repeticiones por equipo.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 10, materials: "Balón, arco, petos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Transición ofensiva vertical", description: "Al recuperar el balón en zona media, el equipo debe llegar al arco rival en máximo 4 pases. Se practican transiciones por el centro (pase filtrado), por banda (pase largo al extremo), y combinada (pared y profundidad). Punto clave: el primer pase tras recuperación debe ser vertical, nunca horizontal. 15 repeticiones alternando tipo de transición.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 8, materials: "Balones, arco, petos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Pressing alto con trampa en banda", description: "Equipo practica dirigir al rival hacia la banda mediante pressing orientado. Cuando el balón llega a la banda, se activa trampa de presión con 3 jugadores cerrando el espacio. Se definen roles claros: presionador, cobertura y cierre. Punto clave: el ángulo de carrera del primer presionador debe cerrar la opción de pase interior. Variación: trampa en ambas bandas.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 11, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Intensidad de carrera con y sin balón", description: "Circuito de alta intensidad que simula las demandas del estilo Liverpool. Secuencia: sprint de 30m, pressing de 10 segundos, trote de recuperación 15 segundos, sprint con balón 20m, pase largo, sprint de vuelta. 6 series con 1 minuto de descanso entre series. Punto clave: mantener la intensidad del sprint en la última serie igual que en la primera.", category: "physical", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 4, materials: "Balones, conos, cronómetro", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Contraataque 4v3 con pressing de vuelta", description: "Situación de 4v3 en contraataque. Si los 4 atacantes no anotan en 8 segundos, los 3 defensores reciben 2 refuerzos y contraatacan 5v4. El ejercicio es continuo sin pausas. Punto clave: la velocidad de decisión en el contraataque y la reacción inmediata al perder. Se juegan periodos de 5 minutos.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 9, materials: "Balones, arcos, petos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Pases directos en transición", description: "Ejercicio de pases a un toque en situación de transición. 4 jugadores en línea reciben y pasan a un toque mientras se desplazan a máxima velocidad hacia el arco. El último jugador define. Se practican 3 patrones: pases directos, pared con devolución, y pase diagonal. Punto clave: la velocidad del balón debe ser mayor que la velocidad de los jugadores.", category: "passing", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 18, playersRequired: 5, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Duelos 1v1 en espacios amplios", description: "Duelos individuales en espacio de 15x15m con arcos en ambos extremos. El atacante debe superar al defensor y anotar. Si el defensor recupera, contraataca al arco opuesto. Se enfatiza la intensidad del duelo y la capacidad de ganar en situaciones de 1v1. Punto clave: el atacante debe atacar el espacio detrás del defensor, no al defensor. 10 duelos por jugador.", category: "individual", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 4, materials: "Balón, mini arcos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: 5v5 de alta intensidad con rotación", description: "Partido 5v5 de máxima intensidad en espacio de 30x25m. Periodos de 2 minutos con cambio completo de equipos. El equipo que descansa hace trabajo de recuperación activa. Gol en los primeros 10 segundos tras inicio vale doble. Punto clave: la intensidad debe ser máxima durante los 2 minutos completos. Se juegan 6 periodos por equipo.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 30, playersRequired: 15, materials: "Balón, arcos, petos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: true, gameFormat: "5v5" },
  { title: "Liverpool: Centros y remates en transición", description: "Ejercicio de finalización que simula contraataque por banda. Extremo recibe pase largo, conduce 10m y centra al área donde llegan 2 atacantes en carrera. Se alternan centros rasos, medios y altos. Punto clave: los atacantes deben llegar al área en carrera, nunca esperando estáticos. Variación: añadir defensor que persigue al extremo.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 5, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Counter-pressing en 3v3+2", description: "Juego 3v3 con 2 comodines. Al perder el balón, el equipo que perdió debe aplicar counter-pressing inmediato. Si recupera en 4 segundos, mantiene posesión. Si no, los comodines cambian de equipo. Espacio de 15x15m. Punto clave: la agresividad del counter-pressing debe ser máxima pero inteligente. Periodos de 3 minutos.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 20, playersRequired: 8, materials: "Balón, conos, petos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: true, gameFormat: "3v3" },
  { title: "Liverpool: Resistencia de alta intensidad repetida", description: "Test y entrenamiento de RSA (Repeated Sprint Ability). 10 sprints de 30m con 20 segundos de recuperación entre cada uno. Se mide el tiempo de cada sprint y se calcula el índice de fatiga. Punto clave: el objetivo es que la diferencia entre el primer y último sprint sea menor al 5%. Variación: añadir cambio de dirección en cada sprint.", category: "physical", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 15, playersRequired: 4, materials: "Conos, cronómetro", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Pase largo diagonal en transición", description: "Mediocampista recibe balón en zona central y debe ejecutar pase largo diagonal de 35m al extremo que arranca en carrera. Se practican pases a ambos lados alternando. El extremo controla y centra. Punto clave: el pase debe caer en el espacio por delante del extremo, no a sus pies. 10 repeticiones por lado.", category: "passing", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 18, playersRequired: 4, materials: "Balones, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
];

// ==================== JUVENTUS ====================
const juventusExercises: ExerciseData[] = [
  { title: "Juventus: Organización defensiva en bloque medio", description: "Línea de 4 defensores y 3 mediocampistas practican basculación coordinada en bloque medio. El balón se mueve entre 4 atacantes y la defensa debe ajustar posiciones manteniendo distancias de 8-10m entre jugadores. Punto clave: el central del lado del balón presiona mientras el otro cubre. Se practican 20 secuencias de basculación. Variación: añadir delantero que busca espacio entre líneas.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 25, playersRequired: 11, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Defensa de córner - marcaje mixto", description: "Organización defensiva en córners con sistema mixto: 3 jugadores en marcaje zonal (primer palo, segundo palo, punto penal) y 4 en marcaje individual. Se practican 15 córners con diferentes tipos de servicio: corto, largo al primer palo, largo al segundo palo, y con variante corta. Punto clave: los marcadores zonales no siguen al atacante, defienden el espacio.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 11, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Línea defensiva - offside trap", description: "Línea de 4 defensores practica la trampa del fuera de juego. Se coordinan para subir la línea en el momento exacto del pase del rival. Se practican 3 escenarios: pase desde el centro, pase desde la banda, y pase largo. Punto clave: todos los defensores deben subir al mismo tiempo, el más lento marca el timing. 20 repeticiones con análisis de video.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 8, materials: "Balones, conos, petos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Tiro libre con barrera - rutinas ofensivas", description: "Práctica de 5 rutinas de tiro libre ofensivo con barrera. Rutina 1: tiro directo con efecto. Rutina 2: pase corto y tiro. Rutina 3: jugador sale de barrera y remata. Rutina 4: centro al segundo palo. Rutina 5: pase atrás para remate de media distancia. Punto clave: la ejecución debe ser rápida para sorprender. 3 repeticiones por rutina.", category: "shooting", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 8, materials: "Balones, arco, barrera/maniquíes", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Córner ofensivo - 5 variantes", description: "Ensayo de 5 variantes de córner ofensivo. Variante 1: centro directo al primer palo con bloqueo. Variante 2: córner corto con centro retrasado. Variante 3: centro al segundo palo con carrera desde atrás. Variante 4: córner corto con tiro desde fuera del área. Variante 5: centro con movimiento cruzado de atacantes. Punto clave: los movimientos deben ser sincronizados.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 10, materials: "Balones, arco", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Disciplina táctica - mantener forma", description: "Partido 7v7 donde el entrenador detiene el juego aleatoriamente y evalúa si cada jugador está en su zona correcta. Puntos por mantener la forma táctica. Se penaliza al equipo que tiene jugadores fuera de posición. Punto clave: la disciplina posicional es más importante que la creatividad individual. Se juegan 4 periodos de 5 minutos.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 25, playersRequired: 14, materials: "Balón, arcos, petos, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: true, gameFormat: "7v7" },
  { title: "Juventus: Duelo defensivo 1v1 en zona", description: "Defensor practica duelos 1v1 en zona de 10x10m. El atacante intenta cruzar la línea de fondo. El defensor debe usar posicionamiento, timing de entrada y fuerza corporal para impedirlo. Se enfatiza no tirarse al suelo innecesariamente. Punto clave: mantener al atacante de frente y retrasar su avance. 10 duelos por defensor.", category: "individual", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 18, playersRequired: 4, materials: "Balón, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Salida de balón bajo presión alta", description: "Defensa de 4 + portero practican salida de balón contra pressing alto de 4 atacantes. Se trabajan 3 opciones: pase corto entre centrales, pase largo al mediocampista que cae, y pase largo al extremo. El portero decide la opción según la presión. Punto clave: si no hay opción limpia, el portero debe jugar largo sin riesgo. 15 repeticiones.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 9, materials: "Balones, arco, petos, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Defensa de tiro libre - organización de barrera", description: "Práctica de organización defensiva en tiros libres. Se trabaja la colocación de barrera (3, 4 o 5 jugadores según distancia), el posicionamiento del portero, y la cobertura de los jugadores fuera de barrera. Punto clave: la barrera debe saltar coordinadamente y el portero debe ver el balón. 10 repeticiones desde diferentes posiciones.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 10, materials: "Balones, arco", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Repliegue defensivo organizado", description: "Tras perder posesión en zona ofensiva, el equipo debe replegar ordenadamente en máximo 8 segundos formando bloque bajo compacto. Se practican 3 escenarios: pérdida en banda, pérdida en centro, y pérdida tras córner. Punto clave: los delanteros deben ser los primeros en replegar para cerrar espacios centrales. 12 repeticiones con análisis entre cada una.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 11, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Fuerza de tren superior para duelos aéreos", description: "Circuito de fuerza específico para mejorar en duelos aéreos. Incluye: saltos con chaleco lastrado, cabeceos con resistencia, empujes isométricos, y ejercicios de core anti-rotación. 4 estaciones de 45 segundos con 15 de descanso. 3 vueltas. Punto clave: la fuerza del tren superior determina quién gana el duelo aéreo.", category: "physical", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 4, materials: "Balones, chaleco lastrado, bandas, colchoneta", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Saque de banda largo táctico", description: "Práctica de saques de banda largos como arma táctica. El lanzador practica técnica de saque largo (15-20m) mientras los compañeros ensayan movimientos predefinidos en el área. Se trabajan 3 rutinas: saque al primer palo con desvío, saque al segundo palo, y saque corto con combinación. Punto clave: el saque debe llegar con velocidad y precisión.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 8, materials: "Balones, arco", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
];

// ==================== BORUSSIA DORTMUND ====================
const dortmundExercises: ExerciseData[] = [
  { title: "Dortmund: Transición vertical rápida 4v3", description: "Al recuperar balón en zona media, 4 atacantes deben progresar verticalmente contra 3 defensores en máximo 6 segundos. Se enfatiza el primer pase vertical inmediato tras recuperación. Si el ataque no termina en 6 segundos, se reinicia. Punto clave: el jugador que recupera debe levantar la cabeza inmediatamente para encontrar la opción vertical. 12 repeticiones.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 7, materials: "Balones, arco, petos, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Desarrollo juvenil - técnica bajo presión", description: "Ejercicio progresivo de técnica individual donde la presión aumenta gradualmente. Fase 1: control y pase sin oposición. Fase 2: control y pase con defensor pasivo. Fase 3: control y pase con defensor activo. Fase 4: situación real de juego. Cada fase dura 4 minutos. Punto clave: la técnica aprendida sin presión debe mantenerse bajo presión máxima.", category: "ball_control", minAge: 8, maxAge: 14, difficulty: "intermediate", durationMinutes: 20, playersRequired: 4, materials: "Balones, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Contraataque rápido con pase largo", description: "Portero o defensor lanza pase largo de 40m al delantero que arranca en velocidad. El delantero debe controlar en carrera y definir ante el portero rival. Se practican 3 tipos de pase largo: raso, medio y aéreo. Punto clave: el control del delantero debe ser hacia adelante, nunca frenando. 10 repeticiones por tipo de pase.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 4, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Pressing alto juvenil - aprender a presionar", description: "Ejercicio pedagógico para enseñar pressing alto a jugadores jóvenes. Se comienza con pressing 1v1 (un presionador, un portador). Luego 2v1, 2v2, 3v2, hasta llegar a pressing grupal. En cada fase se enseñan los principios: ángulo de carrera, cierre de líneas, y comunicación. Punto clave: la paciencia en la enseñanza progresiva.", category: "tactics", minAge: 8, maxAge: 14, difficulty: "beginner", durationMinutes: 25, playersRequired: 6, materials: "Balones, conos, petos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Velocidad con balón en transición", description: "Circuito de velocidad que simula una transición ofensiva. Sprint de 10m sin balón, recepción de pase en carrera, conducción a máxima velocidad 20m, pase al compañero, sprint de vuelta. Se cronometra el circuito completo. Punto clave: la velocidad con balón debe ser al menos 85% de la velocidad sin balón. 6 repeticiones con descanso completo.", category: "agility", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 18, playersRequired: 4, materials: "Balones, conos, cronómetro", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Juego vertical 5v5 con zonas de transición", description: "Partido 5v5 con 2 zonas de transición de 5m en cada extremo. Al recuperar el balón, el equipo debe pasar por la zona de transición en máximo 3 pases. Gol solo vale si se pasó por la zona de transición. Punto clave: la verticalidad inmediata tras recuperación. Periodos de 4 minutos con descanso de 1 minuto.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 25, playersRequired: 10, materials: "Balón, arcos, petos, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: true, gameFormat: "5v5" },
  { title: "Dortmund: Desarrollo de extremos - 1v1 en banda", description: "Extremo recibe balón en banda y debe superar al lateral en duelo 1v1 para centrar o cortar hacia dentro y tirar. Se practican ambos perfiles: extremo derecho que corta con izquierda y extremo izquierdo que corta con derecha. Punto clave: el primer toque del extremo debe ser hacia adelante para ganar ventaja. 8 repeticiones por lado.", category: "individual", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 18, playersRequired: 4, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Pases verticales progresivos", description: "Ejercicio de pases donde el balón debe progresar siempre hacia adelante. 4 líneas de jugadores separadas 10m. El balón va de la línea 1 a la 4 con pases a un toque. Cuando llega a la línea 4, se reinicia desde la 1. Punto clave: cada pase debe ser hacia adelante, nunca lateral o hacia atrás. Progresión: añadir defensores entre líneas.", category: "passing", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 15, playersRequired: 8, materials: "Balones, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Resistencia de sprints repetidos", description: "Protocolo de sprints repetidos diseñado para el estilo de juego vertical del Dortmund. 8 sprints de 25m con 15 segundos de recuperación activa (trote). Tras los 8 sprints, 2 minutos de descanso y se repite. 3 series totales. Punto clave: mantener la velocidad máxima en cada sprint sin importar la fatiga acumulada.", category: "physical", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 4, materials: "Conos, cronómetro", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: 7v7 con énfasis en transiciones", description: "Partido 7v7 donde cada gol se inicia con saque del portero del equipo que recibió el gol (no del que anotó). Esto crea transiciones constantes. Gol en transición (dentro de 8 segundos de recuperar) vale doble. Punto clave: ambos equipos deben estar preparados para atacar y defender en todo momento. Periodos de 5 minutos.", category: "tactics", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 30, playersRequired: 14, materials: "Balón, arcos, petos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: true, gameFormat: "7v7" },
  { title: "Dortmund: Creatividad juvenil - juego libre con objetivos", description: "Juego libre 4v4 donde los jugadores jóvenes tienen libertad total de movimiento y decisión. El único objetivo es divertirse y ser creativos. El entrenador no interviene durante el juego, solo observa. Después de cada periodo de 5 minutos, se hace una breve reflexión grupal. Punto clave: fomentar la creatividad y la toma de riesgos sin miedo al error.", category: "tactics", minAge: 6, maxAge: 12, difficulty: "beginner", durationMinutes: 25, playersRequired: 8, materials: "Balón, mini arcos, petos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: true, gameFormat: "4v4" },
  { title: "Dortmund: Finalización en transición rápida", description: "Ejercicio de finalización que simula gol en transición. Mediocampista recupera balón en zona central y tiene 3 opciones: pase al delantero que viene de frente, pase al extremo que arranca por banda, o conducción y tiro propio. El entrenador indica la opción con señal visual. Punto clave: la decisión debe tomarse antes de recibir el balón.", category: "shooting", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 5, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
];

// ==================== GOALKEEPING (NEW CATEGORY) ====================
const goalkeepingExercises: ExerciseData[] = [
  { title: "Portero: Blocaje alto y bajo", description: "Práctica de blocaje en dos alturas. Serie de 10 tiros a media altura y 10 tiros rasos. El portero debe atrapar con técnica correcta: manos en W para tiros altos, cuerpo detrás del balón para tiros bajos. Punto clave: la posición de las manos y la amortiguación del balón contra el pecho. Progresión: aumentar potencia de tiros.", category: "goalkeeping", minAge: 8, maxAge: 14, difficulty: "beginner", durationMinutes: 15, playersRequired: 2, materials: "Balones, arco, guantes", diagramUrl: null, methodologySource: "Chelsea FC", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Estiradas laterales", description: "Portero practica estiradas laterales a ambos lados. Se comienza de rodillas, luego de pie, y finalmente con desplazamiento previo. 8 estiradas por lado. Punto clave: la pierna de impulso debe empujar hacia el balón y las manos deben llegar primero que el cuerpo. Variación: añadir rebote para segunda acción.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 18, playersRequired: 2, materials: "Balones, arco, guantes, colchoneta", diagramUrl: null, methodologySource: "Bayern Munich", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Distribución con pie - pase corto y largo", description: "Portero practica distribución con los pies. Serie 1: pases cortos a 15m con interior. Serie 2: pases medios a 25m con empeine. Serie 3: pases largos a 40m con empeine. 10 repeticiones por serie. Punto clave: la precisión es más importante que la potencia. El pase debe llegar al pecho del receptor. Variación: distribución bajo presión.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 3, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Salida en 1v1 - timing y posicionamiento", description: "Delantero recibe pase en profundidad y el portero debe decidir cuándo salir. Se practican 3 escenarios: salida temprana (cortar el pase), salida media (achicar ángulo), y permanencia en línea. Punto clave: la decisión de salir debe tomarse antes de que el delantero controle. 10 repeticiones por escenario. Variación: añadir segundo delantero.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 3, materials: "Balones, arco, guantes", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Juego aéreo - salidas en centros", description: "Práctica de salidas en centros desde banda. Se trabajan centros al primer palo, segundo palo y zona central. El portero debe decidir entre salir a atrapar, despejar con puños, o quedarse en línea. Punto clave: la comunicación con los defensores es fundamental - el portero debe gritar 'mía' o 'fuera'. 15 centros por lado.", category: "goalkeeping", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 6, materials: "Balones, arco, guantes", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Reflejos con rebotes", description: "Tiros desde 8m que rebotan en una superficie irregular antes de llegar al portero. El portero debe reaccionar al rebote impredecible. 20 tiros por serie, 3 series. Punto clave: mantener posición baja y equilibrada para reaccionar en cualquier dirección. Variación: usar tabla de rebote o balón de rugby para rebotes más impredecibles.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 2, materials: "Balones, arco, guantes, tabla de rebote", diagramUrl: null, methodologySource: "Real Madrid", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Posicionamiento según ángulo de tiro", description: "Portero practica posicionamiento correcto según la ubicación del balón. Se colocan conos en 8 posiciones diferentes alrededor del área y el portero debe posicionarse correctamente para cada una. Punto clave: el portero debe cubrir el palo cercano y dejar espacio mínimo al palo lejano. Se verifica con tiros desde cada posición.", category: "goalkeeping", minAge: 8, maxAge: 16, difficulty: "beginner", durationMinutes: 15, playersRequired: 2, materials: "Balones, arco, guantes, conos", diagramUrl: null, methodologySource: null, isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Doble acción - parada y recuperación", description: "Portero realiza primera parada y debe recuperarse inmediatamente para una segunda acción. Secuencia: tiro al primer palo + rebote al segundo palo. Se practican 10 secuencias de doble acción. Punto clave: la velocidad de recuperación tras la primera parada determina el éxito de la segunda. Variación: triple acción con centro posterior.", category: "goalkeeping", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 18, playersRequired: 3, materials: "Balones, arco, guantes", diagramUrl: null, methodologySource: "Bayern Munich", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Construcción desde atrás bajo presión", description: "Portero practica inicio de juego con pase corto a centrales bajo presión de 1, 2 y 3 delanteros. Debe leer la presión y elegir la opción correcta: pase corto al central libre, pase al lateral, o pase largo. Punto clave: el portero debe comunicar la opción antes de recibir el balón. 15 repeticiones con presión progresiva.", category: "goalkeeping", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 7, materials: "Balones, arco, petos, conos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Penaltis - lectura del tirador", description: "Práctica de penaltis enfocada en la lectura del tirador. El portero analiza la carrera, la posición del pie de apoyo y la mirada del tirador para anticipar la dirección. Se practican 20 penaltis con diferentes tiradores. Punto clave: el portero debe esperar hasta el último momento y leer las señales corporales. Análisis posterior de aciertos.", category: "goalkeeping", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 4, materials: "Balones, arco, guantes", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Agilidad y footwork específico", description: "Circuito de agilidad específico para porteros. Incluye: desplazamientos laterales entre postes, saltos sobre vallas bajas con caída y parada, sprint corto con estirada, y recuperación de posición. 4 vueltas al circuito. Punto clave: los pies nunca deben cruzarse durante los desplazamientos laterales.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 2, materials: "Arco, vallas bajas, conos, guantes", diagramUrl: null, methodologySource: "Real Madrid", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Comunicación y organización defensiva", description: "Portero dirige la línea defensiva durante ejercicio de ataque vs defensa. Debe comunicar constantemente: posición de la línea, marcajes, y alertas de peligro. Se evalúa la calidad y frecuencia de la comunicación. Punto clave: el portero es el director de la defensa y debe hablar antes de que ocurra la acción. 15 minutos de juego con evaluación.", category: "goalkeeping", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 20, playersRequired: 10, materials: "Balones, arco, petos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Portero: Saque de meta largo y corto", description: "Práctica de saques de meta con dos objetivos: precisión en pase corto al central (15m) y distancia en pase largo al mediocampista (40m). 10 repeticiones de cada tipo. Punto clave: en el saque corto, el balón debe llegar al pie del receptor; en el largo, debe caer en zona accesible. Variación: saque de meta bajo presión de delantero.", category: "goalkeeping", minAge: 10, maxAge: 18, difficulty: "beginner", durationMinutes: 15, playersRequired: 3, materials: "Balones, arco, conos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
];

// ==================== ADDITIONAL MIXED EXERCISES (NEW ACADEMIES) ====================
const additionalNewAcademyExercises: ExerciseData[] = [
  // Real Madrid additional
  { title: "La Fábrica: Rondo posicional con 3 zonas", description: "Rondo 8v3 en espacio dividido en 3 zonas. Los atacantes deben mover el balón entre zonas con máximo 2 toques. Los defensores solo pueden presionar en la zona donde está el balón. Punto clave: el cambio de zona debe ser rápido y con pase preciso. Rotación de defensores cada 2 minutos. Desarrolla la visión de juego y el cambio de orientación.", category: "passing", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 11, materials: "Balón, conos, petos", diagramUrl: null, methodologySource: "Real Madrid", isSmallSidedGame: false, gameFormat: null },
  { title: "La Fábrica: Velocidad de ejecución técnica", description: "Circuito cronometrado de acciones técnicas: recepción, control orientado, pase a 15m, sprint 10m, recepción en carrera, conducción 15m, tiro al arco. Se mide el tiempo total y la calidad de cada acción. Punto clave: la velocidad no debe comprometer la calidad técnica. 5 repeticiones buscando mejorar el tiempo.", category: "individual", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 18, playersRequired: 3, materials: "Balones, arco, conos, cronómetro", diagramUrl: null, methodologySource: "Real Madrid", isSmallSidedGame: false, gameFormat: null },
  // Bayern additional
  { title: "Bayern: Pressing escalonado en 3 líneas", description: "Equipo completo practica pressing escalonado. Línea 1 (delanteros) presiona al portador. Línea 2 (mediocampistas) cierra líneas de pase. Línea 3 (defensores) sube para achicar. Se practican 3 triggers: pase hacia atrás, mal control, y balón aéreo. Punto clave: las 3 líneas deben moverse como una unidad compacta.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 11, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Bayern Munich", isSmallSidedGame: false, gameFormat: null },
  { title: "Bayern: Entrenamiento cognitivo con números", description: "Jugadores numerados del 1 al 8 en espacio de 20x20m. El entrenador grita un número y ese jugador debe presionar al portador del balón. Los demás deben ajustar posiciones. Punto clave: la velocidad de procesamiento de la información y la reacción colectiva. Variación: gritar operaciones matemáticas cuyo resultado indica el presionador.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 18, playersRequired: 9, materials: "Balón, petos numerados, conos", diagramUrl: null, methodologySource: "Bayern Munich", isSmallSidedGame: false, gameFormat: null },
  // Manchester City additional
  { title: "City: Posesión 3-2-3 con progresión", description: "Posesión con estructura 3-2-3 (3 defensores, 2 mediocampistas, 3 atacantes) contra 6 defensores. El objetivo es progresar el balón desde la línea defensiva hasta la línea de ataque. Punto clave: los mediocampistas deben ofrecer líneas de pase entre las líneas defensivas rivales. Gol si el balón llega a los 3 atacantes con pase limpio.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 14, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: false, gameFormat: null },
  { title: "City: Recepción perfilada en zona de creación", description: "Mediocampista recibe en zona de creación (entre líneas) con cuerpo perfilado hacia el arco rival. Se practican recepciones desde 4 ángulos diferentes. Punto clave: el perfil del cuerpo al recibir debe permitir ver el arco y las opciones de pase simultáneamente. 15 recepciones por ángulo. Progresión: añadir defensor.", category: "ball_control", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 4, materials: "Balones, conos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: false, gameFormat: null },
  // Liverpool additional
  { title: "Liverpool: Pressing coordinado del tridente", description: "Los 3 delanteros practican pressing coordinado. El central presiona al portador, los extremos cierran las opciones de pase a los laterales. Se definen ángulos de carrera específicos para cada delantero. Punto clave: el pressing del tridente debe funcionar como una unidad, no como 3 individuos. 15 repeticiones con análisis.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 20, playersRequired: 7, materials: "Balones, petos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  { title: "Liverpool: Intensidad de duelos en espacio reducido", description: "Duelos 1v1 en espacio de 5x5m con mini arcos. Máxima intensidad durante 30 segundos. Descanso de 30 segundos. 8 duelos por jugador. Punto clave: la intensidad del duelo debe simular un momento decisivo de partido. Se evalúa agresividad, técnica y determinación.", category: "individual", minAge: 10, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 4, materials: "Balón, mini arcos, conos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: false, gameFormat: null },
  // Juventus additional
  { title: "Juventus: Defensa en inferioridad 3v4", description: "3 defensores practican contener ataque de 4 atacantes. El objetivo es retrasar el ataque hasta que lleguen refuerzos (simulados con tiempo). Se enfatiza no tirarse al suelo, mantener posición y cubrir el centro. Punto clave: el defensor central debe organizar a los otros dos y priorizar cubrir el arco.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 18, playersRequired: 8, materials: "Balones, arco, petos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  { title: "Juventus: Cabeceo defensivo y ofensivo", description: "Práctica de cabeceo en dos fases. Fase defensiva: despejar centros con potencia y dirección (hacia las bandas). Fase ofensiva: rematar centros con precisión hacia las esquinas del arco. 10 cabeceos defensivos y 10 ofensivos. Punto clave: en defensa, atacar el balón; en ataque, redirigir con cuello.", category: "individual", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 15, playersRequired: 4, materials: "Balones, arco", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: false, gameFormat: null },
  // Dortmund additional
  { title: "Dortmund: Desarrollo de talento - libertad creativa", description: "Sesión de entrenamiento donde los jugadores jóvenes eligen sus propios ejercicios y organizan mini-juegos. El entrenador solo observa y toma notas. Después de 20 minutos de juego libre, se hace una reflexión grupal sobre lo aprendido. Punto clave: fomentar la autonomía y la creatividad sin restricciones tácticas.", category: "individual", minAge: 6, maxAge: 12, difficulty: "beginner", durationMinutes: 25, playersRequired: 8, materials: "Balones, conos, mini arcos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: false, gameFormat: null },
  { title: "Dortmund: Transición rápida 3v2 continua", description: "Juego continuo de 3v2 donde al anotar o perder, los roles se invierten inmediatamente. Los 3 atacantes pasan a defender y los 2 defensores reciben un refuerzo para atacar 3v2. Sin pausas. Punto clave: la velocidad de adaptación mental al cambiar de rol. Periodos de 4 minutos.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 20, playersRequired: 6, materials: "Balón, mini arcos, petos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: true, gameFormat: "3v2" },
  // Mixed new academy small-sided games
  { title: "8v8 posicional con pressing triggers (City)", description: "Partido 8v8 con porteros donde el pressing solo se activa con triggers específicos: pase hacia atrás, control con suela, o balón en zona lateral. Fuera de triggers, equipos mantienen bloque. Punto clave: la disciplina de esperar el trigger y la explosividad al activarse. Periodos de 6 minutos.", category: "tactics", minAge: 14, maxAge: 18, difficulty: "advanced", durationMinutes: 30, playersRequired: 18, materials: "Balón, arcos, petos, conos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: true, gameFormat: "8v8" },
  { title: "6v6 de transiciones rápidas (Dortmund)", description: "Partido 6v6 con énfasis en transiciones. Al recuperar, el equipo tiene 10 segundos para anotar. Si no anota, pierde posesión automáticamente. Gol en transición vale triple. Punto clave: la mentalidad de atacar inmediatamente tras recuperar. Periodos de 4 minutos con alta intensidad.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 12, materials: "Balón, arcos, petos", diagramUrl: null, methodologySource: "Borussia Dortmund", isSmallSidedGame: true, gameFormat: "6v6" },
  { title: "4v4 con portero-jugador estilo City", description: "Partido 4v4 donde el portero participa activamente como jugador de campo cuando su equipo tiene posesión, creando superioridad 5v4. Al perder, debe volver rápidamente al arco. Punto clave: el portero debe leer cuándo salir y cuándo quedarse. Desarrolla la filosofía del portero-libero de Guardiola.", category: "tactics", minAge: 10, maxAge: 16, difficulty: "intermediate", durationMinutes: 20, playersRequired: 10, materials: "Balón, arcos, petos", diagramUrl: null, methodologySource: "Manchester City", isSmallSidedGame: true, gameFormat: "4v4" },
  { title: "5v5 gegenpressing intensivo (Liverpool)", description: "Partido 5v5 donde al perder el balón, el equipo tiene exactamente 4 segundos para aplicar gegenpressing. Si no recupera en 4 segundos, el rival recibe un jugador extra (6v5) durante 10 segundos. Punto clave: la reacción colectiva inmediata al perder posesión. Periodos de 3 minutos de máxima intensidad.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 12, materials: "Balón, arcos, petos", diagramUrl: null, methodologySource: "Liverpool", isSmallSidedGame: true, gameFormat: "5v5" },
  { title: "7v7 con disciplina táctica (Juventus)", description: "Partido 7v7 donde el entrenador congela el juego aleatoriamente y verifica la posición de cada jugador. Equipo con mejor organización defensiva recibe punto extra. Se evalúa distancia entre líneas, cobertura de espacios y marcajes. Punto clave: la disciplina táctica debe mantenerse incluso en momentos de ataque.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "intermediate", durationMinutes: 30, playersRequired: 14, materials: "Balón, arcos, petos, conos", diagramUrl: null, methodologySource: "Juventus", isSmallSidedGame: true, gameFormat: "7v7" },
  { title: "3v3 técnico estilo La Fábrica", description: "Juego 3v3 en espacio reducido de 15x12m donde se premia la calidad técnica. Gol con control orientado previo vale doble. Gol con regate previo vale triple. Gol de primera vale doble. Punto clave: fomentar la excelencia técnica en situaciones de juego real. Periodos de 3 minutos.", category: "ball_control", minAge: 8, maxAge: 14, difficulty: "intermediate", durationMinutes: 20, playersRequired: 6, materials: "Balón, mini arcos, petos", diagramUrl: null, methodologySource: "Real Madrid", isSmallSidedGame: true, gameFormat: "3v3" },
  { title: "Bayern: 6v6 con zonas de pressing obligatorio", description: "Partido 6v6 con zonas marcadas donde el pressing es obligatorio. Si el balón entra en zona roja, todo el equipo debe presionar. En zona verde, solo pressing del jugador más cercano. Punto clave: la lectura colectiva de cuándo presionar con intensidad y cuándo contener. Periodos de 5 minutos.", category: "tactics", minAge: 12, maxAge: 18, difficulty: "advanced", durationMinutes: 25, playersRequired: 12, materials: "Balón, arcos, petos, conos de colores", diagramUrl: null, methodologySource: "Bayern Munich", isSmallSidedGame: true, gameFormat: "6v6" },
];

